def oracle(m):
 k=m['kind']
 if k=='weighted':
  expanded=[v for v,n in zip(m['values'],m['freq']) for _ in range(n)];n=len(expanded);s=sum(expanded);avg=F(s,n);assert n==m['expected_count'] and s==m['expected_sum'] and avg==F(m['expected_mean']);return dict(expanded_observations=expanded,count=n,total=s,mean=str(avg),decimal_mean=str(D(s)/D(n)))
 if k=='swap':
  trials=[];valid=[]
  for i,j in combinations(range(len(m['digits'])),2):
   ds=list(m['digits']);ds[i],ds[j]=ds[j],ds[i];text=''.join(ds);ok=ds[0]!='0' and int(ds[-1])in[1,3,5,7,9];row=dict(positions=[i+1,j+1],numeral=text,valid=ok);trials.append(row)
   if ok:valid.append(row)
  best=max(int(x['numeral'])for x in valid);pairs=[x['positions']for x in valid if int(x['numeral'])==best];assert best==m['expected_max'] and pairs==m['expected_pairs'];return dict(all_position_pairs=trials,maximum=best,maximizing_pairs=pairs)
 if k=='whole_pieces':
  total,reserve,size=map(F,[m['total'],m['reserve'],m['size']]);available=total-reserve;allowed=[n for n in range(101)if n*size<=available];n=max(allowed);free=available-n*size;unused=total-n*size;assert n==m['expected_n'] and free==F(m['expected_free']) and unused==F(m['expected_unused']) and (n+1)*size>available;return dict(valid_integer_counts=allowed,maximum=n,free_remainder=str(free),unused_including_reserve=str(unused),one_more_required=str((n+1)*size),available=str(available),boundary_completeness='size>0 and101×size>available; larger counts cannot be feasible')
 if k=='tile_boxes':
  l,w,t=map(F,[m['length'],m['width'],m['tile']]);nx=l/t;ny=w/t;assert nx.denominator==ny.denominator==1;cells={(room,x,y)for room in range(m['rooms'])for x in range(nx.numerator)for y in range(ny.numerator)};tiles=len(cells);need=tiles+m['spares'];valid=[n for n in range(101)if m['stock']+n*m['pack']>=need];boxes=min(valid);cost=boxes*m['price'];unused=m['stock']+boxes*m['pack']-tiles;assert [tiles,boxes,cost,unused]==[m['expected_tiles'],m['expected_boxes'],m['expected_cost'],m['expected_unused']];assert boxes==0 or m['stock']+(boxes-1)*m['pack']<need;return dict(grid_columns=nx.numerator,grid_rows=ny.numerator,room_count=m['rooms'],tile_count=tiles,required_with_spares=need,minimum_boxes=boxes,cost=cost,unused=unused,spares=m['spares'])
 if k=='pack_share':
  total=m['packs']*m['perpack']+m['loose'];pieces=F(total,m['people']);selected=[]
  for label,op in m['options'].items():
   amount=F(op['value'])*(m['perpack']if op['unit']=='pack' else 1)
   if amount==pieces:selected.append(label)
  assert pieces==F(m['expected_pieces']) and selected==m['expected_options'];return dict(total_pieces=total,pieces_per_person=str(pieces),equivalent_options=selected)
 if k=='sealed_share':
  # Enumerate possible equal whole-pack allocations to every group, without
  # opening, discarding, or duplicating a pack.
  valid=[a for a in range(m['packs']+1)if a*m['people']==m['packs']];assert bool(valid)==m['expected_possible'];return dict(equal_whole_pack_counts=valid,all_possible_counts_checked=list(range(m['packs']+1)),arithmetic_pieces_per_group=str(F(m['packs']*m['perpack'],m['people'])))
 if k=='rim':
  d,p,j,c=map(F,[m['diameter'],m['pi'],m['join'],m['capacity']]);circ=d*p;need=circ+j;margin=c-need;yes=margin>=0;nd=D(m['diameter'])*D(m['pi'])+D(m['join']);assert need==F(m['expected_need']) and yes==m['expected_feasible'] and margin==F(m['expected_margin']) and F(nd)==need;return dict(circumference=str(circ),join=str(j),need=str(need),capacity=str(c),signed_surplus=str(margin),feasible=yes,decimal_need=str(nd),equality_allowed=True)
 raise ValueError(k)

