  x=re.sub(r'(điểm|Điểm|phải|có|gồm|theo|Kiểm|kiểm|tổng|ghi|tạo|khác|lên|gần|dùng|gọi|Vậy|cạnh|nhật|thêm|hộp|sàn|phòng|cộng|lát|gói|thương|Thương|xuất|tức|kính|đa|hơn|vượt|vi|trí|cùng|nghìn|rộng)(?=\d)',r'\1 ',x)
